302	
303	    /**
304	     * The owner's current primary identifier, carried by the structured {@link OwnerCreatedEvent}.
305	     * Today an owner's primary identifier is its {@code customerCode}; this single accessor is the one
306	     * place that decides which field is primary, so if a later change unifies the customer code into a
307	     * member id, redirecting this method to the member id makes the audit event carry it instead.
308	     *
309	     * @param owner the created owner
310	     * @return the owner's current primary identifier
311	     */
312	    private String primaryIdentifier(Owner owner) {
313	        return owner.getCustomerCode();
314	    }
315	
316	    /**
317	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where REGION is
318	     * the region derived from the owner's postcode (preferring the postcode, falling back to the
319	     * city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}) and HASH8 is the
320	     * first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized E.164
321	     * telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no
322	     * sequence number, so its base form is a stable function of the owner's region and
323	     * telephone/last-name identity rather than of creation order.
324	     *
325	     * <p>When that computed code already belongs to an existing owner it is de-duplicated by
326	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a code no
327	     * existing owner already has; the de-duplicated code is returned.
328	     *
329	     * @param owner the owner being created, with its telephone already normalized to E.164 form
330	     * @return the assigned, collision-free customer code
331	     */
332	    private String customerCodeFor(Owner owner) {
333	        String region = ownerMapper.regionOf(owner);
334	        String hash8 = IdentityKeyUtils.sha256UpperHex(owner.getTelephone() + owner.getLastName())
335	            .substring(0, 8);
336	        String baseCode = region + "-" + hash8;
337	        if (!isCustomerCodeInUse(baseCode)) {
338	            return baseCode;
339	        }
340	        int n = 2;
341	        String candidate = baseCode + "-" + n;
342	        while (isCustomerCodeInUse(candidate)) {
343	            n++;
344	            candidate = baseCode + "-" + n;
345	        }
346	        return candidate;
347	    }
348	
349	    /**
350	     * Determines whether any existing owner already carries the given {@code customerCode}, compared
351	     * exactly. Called while assigning a new owner's code so collisions can be de-duplicated.
352	     *
353	     * @param customerCode the candidate customer code to look for
354	     * @return {@code true} if an existing owner already has that customer code
355	     */
356	    private boolean isCustomerCodeInUse(String customerCode) {
357	        for (Owner existing : this.clinicService.findAllOwners()) {
358	            if (customerCode.equals(existing.getCustomerCode())) {
359	                return true;
360	            }
361	        }
362	        return false;
363	    }
364	
365	    /**
366	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
367	     * owner's city already contains this many owners.
368	     */
369	    private static final int CITY_CAPACITY = 50;
370	
371	    /**
372	     * The maximum number of owners that may be created on a single day. A create is rejected with
373	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
374	     * {@code registrationDate}.
375	     */
376	    private static final int DAILY_CREATE_LIMIT = 100;
377	
378	    /**
379	     * The number of owners that must already have been created for the current day before a new
380	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
381	     * owners already carry today's {@code registrationDate}.
382	     */
383	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
384	
385	    /**
386	     * The fixed public holidays that the business-day roll skips. A registration date landing on one
387	     * of these dates is rolled forward, exactly as it is for a weekend day.
388	     */
389	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
390	        LocalDate.parse("2026-01-01"),
391	        LocalDate.parse("2026-01-26"),
392	        LocalDate.parse("2026-04-25"),
393	        LocalDate.parse("2026-12-25"),
394	        LocalDate.parse("2026-12-28"));
395	
396	    /**
397	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday, a
398	     * Sunday or a listed public holiday is advanced one day at a time until it lands on a weekday
399	     * that is not a public holiday, while a date already on a non-holiday weekday is returned
400	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
401	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
402	     * falls on a business day.
403	     *
404	     * @param date the effective registration date
405	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
406	     */
407	    private static LocalDate rollToBusinessDay(LocalDate date) {
408	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
409	            date = date.plusDays(1);
410	        }
411	        return date;
412	    }
413	
414	    private static boolean isWeekend(LocalDate date) {
415	        return switch (date.getDayOfWeek()) {
416	            case SATURDAY, SUNDAY -> true;
417	            default -> false;
418	        };
419	    }
420	
421	    /**
422	     * Counts the existing owners whose {@code registrationDate} equals the given (already
423	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
424	     * business day. Called before a new owner is saved, so the returned value reflects the number of
425	     * owners created for that day prior to this create.
426	     *
427	     * @param date the adjusted business-day registration date to count against
428	     * @return the number of existing owners registered on that date
429	     */
430	    private int countOwnersRegisteredOn(LocalDate date) {
431	        return (int) this.clinicService.findAllOwners().stream()
432	            .filter(existing -> date.equals(existing.getRegistrationDate()))
433	            .count();
434	    }
435	
436	    /**
437	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
438	     *
439	     * @param city the city to count owners for
440	     * @return the number of existing owners in that city
441	     */
442	    private int countOwnersInCity(String city) {
443	        return (int) this.clinicService.findAllOwners().stream()
444	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
445	            .count();
446	    }
447	
448	    /**
449	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
450	     * the last two digits of the fiscal year (which starts on 1 July) of the business-day-adjusted
451	     * registration date (e.g. {@code 'NSW-1A2B3C4D-M27'}). The fiscal year is derived via
452	     * {@link OwnerMapper#fiscalYear(LocalDate)}, the single source of truth also used by the DTO's
453	     * {@code fiscalYear} field.
454	     *
455	     * @param customerCode     the owner's assigned customer code
456	     * @param registrationDate the owner's business-day-adjusted registration date
457	     * @return the assigned membership number
458	     */
459	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
460	        String yy = String.format("%02d", OwnerMapper.fiscalYear(registrationDate) % 100);
461	        return String.format("%s-M%s", customerCode, yy);
462	    }
463	
464	    /**
465	     * Counts the existing owners that already share the given first name and last name, comparing
466	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
467	     * the number of namesakes that existed prior to this create.
468	     *
469	     * @param firstName the new owner's first name
470	     * @param lastName  the new owner's last name
471	     * @return the number of existing owners with the same first and last name
472	     */
473	    private int countNamesakes(String firstName, String lastName) {
474	        int count = 0;
475	        for (Owner existing : this.clinicService.findAllOwners()) {
476	            if (firstName.equalsIgnoreCase(existing.getFirstName())
477	                && lastName.equalsIgnoreCase(existing.getLastName())) {
478	                count++;
479	            }
480	        }
481	        return count;
482	    }
483	
484	    /**
485	     * Counts the existing owners that already belong to the given household (i.e. that share the
486	     * given {@code householdId}). Called before a new owner is saved, so adding one for the owner
487	     * being created yields the household's total size at the moment of creation. Owners without a
488	     * household id are ignored.
489	     *
490	     * @param householdId the new owner's assigned household id
491	     * @return the number of existing owners already in that household
492	     */
493	    private int countHouseholdMembers(String householdId) {
494	        if (householdId == null) {
495	            return 0;
496	        }
497	        int count = 0;
498	        for (Owner existing : this.clinicService.findAllOwners()) {
499	            if (householdId.equals(existing.getHouseholdId())) {
500	                count++;
501	            }
502	        }
503	        return count;
504	    }
505	
506	    /**
507	     * Computes the membership-level ceiling for a new owner joining the given household: one above the
508	     * current maximum effective membership level among the existing owners in that household. The
509	     * ceiling is frozen on the owner at creation and later applied by
510	     * {@link OwnerMapper#toMembershipLevel(Owner)}. Returns {@code null} when the household has no
511	     * existing member (or the owner has no household id), meaning no cap applies.
512	     *
513	     * @param householdId the new owner's assigned household id
514	     * @return one above the household's current maximum membership level, or {@code null} when the
515	     *         household has no existing member
516	     */
517	    private Integer householdMembershipLevelCap(String householdId) {
518	        if (householdId == null) {
519	            return null;
520	        }
521	        Integer maxLevel = null;
522	        for (Owner existing : this.clinicService.findAllOwners()) {
523	            if (householdId.equals(existing.getHouseholdId())) {
524	                int level = ownerMapper.toMembershipLevel(existing);
525	                if (maxLevel == null || level > maxLevel) {
526	                    maxLevel = level;
527	                }
528	            }
529	        }
530	        return maxLevel == null ? null : maxLevel + 1;
531	    }
532	
533	    /**
534	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
535	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
536	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
537	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
538	     * string is what gets stored and returned.
539	     *
540	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
541	     *
542	     * <p>Once in E.164 form the national-number length is validated against the country code: a
543	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
544	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
545	     * rule are accepted on the general 8-to-15 digit length alone.
546	     *
547	     * @param telephone the raw telephone value supplied by the client
548	     * @return the normalized E.164 telephone number
549	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
550	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
551	     *                                 after the {@code '+'}, or the wrong national-number length for
552	     *                                 its country code)
553	     */
554	    private static String normalizeTelephone(String telephone) {
555	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
556	        String digits;
557	        if (cleaned.startsWith("+")) {
558	            digits = cleaned.substring(1);
559	        } else {
560	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
561	            digits = "61" + national;
562	        }
563	        if (!digits.matches("[0-9]{8,15}")) {
564	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
565	                "telephone could not be normalized to a valid E.164 number");
566	        }
567	        validateNationalNumberLength(digits);
568	        return "+" + digits;
569	    }
570	
571	    /**
572	     * Validates the national-number length of an E.164 number (its digits, without the leading
573	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
574	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
575	     * (only the general 8-to-15 digit rule applies).
576	     *
577	     * @param digits the E.164 digits without the leading {@code '+'}
578	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
579	     *                                 digits does not match the country code's required length
580	     */
581	    private static void validateNationalNumberLength(String digits) {
582	        E164PhoneNumbers.countryCode(digits)
583	            .ifPresent(code -> {
584	                int nationalLength = digits.length() - code.length();
585	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
586	                if (nationalLength != required) {
587	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
588	                        "telephone must have " + required
589	                            + " national digits for country code +" + code);
590	                }
591	            });
592	    }
593	
594	    /**
595	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
596	     * containing at least one dot, none of the three sections containing whitespace or an
597	     * additional {@code @}.
598	     */
599	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
600	
601	    /**
602	     * Disposable email domains that are not accepted for an owner. An email whose domain is on this
603	     * blocklist is rejected with {@link HttpStatus#BAD_REQUEST}. Entries are lower-case and matched
604	     * case-insensitively against the domain (the part after the {@code @}).
605	     */
606	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
607	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
608	
609	    /**
610	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
611	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
612	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
613	     * lower-cased.
614	     *
615	     * @param email the raw email value supplied by the client, possibly {@code null}
616	     * @return the lower-cased email, or {@code null} when none was supplied
617	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
618	     *                                 is not a syntactically valid address, or its domain is on the
619	     *                                 disposable-domain blocklist
620	     */
621	    private static String normalizeEmail(String email) {
622	        if (email == null) {
623	            return null;
624	        }
625	        if (!EMAIL_PATTERN.matcher(email).matches()) {
626	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
627	                "email must be a syntactically valid address");
628	        }
629	        String normalized = email.toLowerCase(Locale.ROOT);
630	        String domain = normalized.substring(normalized.indexOf('@') + 1);
631	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
632	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
633	                "email domain " + domain + " is not allowed");
634	        }
635	        return normalized;
636	    }
637	
638	    /**
639	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
640	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
641	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
642	     */
643	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
644	        "NSW", new int[] {2000, 2099},
645	        "VIC", new int[] {3000, 3099},
646	        "QLD", new int[] {4000, 4099});
647	
648	    /**
649	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
650	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
651	     * four-digit format is enforced by request validation; here the value is range-checked: when the
652	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
653	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
654	     * accepts any four-digit postcode.
655	     *
656	     * @param city     the owner's city
657	     * @param postcode the owner's postcode, possibly {@code null}
658	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
659	     *                                 out of range for the city's region
660	     */
661	    private static void validatePostcode(String city, String postcode) {
662	        if (postcode == null) {
663	            return;
664	        }
665	        String region = OwnerMapper.CITY_REGION.get(city);
666	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
667	        if (range == null) {
668	            return;
669	        }
670	        int value = Integer.parseInt(postcode);
671	        if (value < range[0] || value > range[1]) {
672	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
673	                "postcode " + postcode + " is not valid for region " + region);
674	        }
675	    }
676	
677	    /**
678	     * Common street-type abbreviations expanded to their full word during address normalization.
679	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
680	     */
681	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
682	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
683	
684	    /**
685	     * Applies an owner's address, accepting either the structured form (a non-blank
686	     * {@code addressLine1} with an optional {@code addressLine2}) or the flat {@code address} form,
687	     * preferring the structured fields when present. Whichever fields are supplied are normalized
688	     * (see {@link #normalizeAddress(String)}), and the stored flat {@code address} is set to the
689	     * composed value: the normalized {@code addressLine1}, with a single space and the normalized
690	     * {@code addressLine2} appended when an {@code addressLine2} was supplied. When only the flat
691	     * form is supplied, the normalized flat address is stored and both structured lines are cleared.
692	     * This keeps the request contract backward-compatible: an owner that supplied just the flat
693	     * {@code address} (plus city) is still accepted.
694	     *
695	     * @param owner the owner being created or updated, carrying the raw address fields
696	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if neither a non-blank
697	     *                                 {@code addressLine1} nor a non-blank flat {@code address} was
698	     *                                 supplied
699	     */
700	    private static void applyAddress(Owner owner) {
701	        boolean hasStructured = owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank();
702	        boolean hasFlat = owner.getAddress() != null && !owner.getAddress().isBlank();
703	        if (!hasStructured && !hasFlat) {
704	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
705	                "an address must be supplied, either 'addressLine1' or 'address'");
706	        }
707	        if (hasStructured) {
708	            String line1 = normalizeAddress(owner.getAddressLine1());
709	            owner.setAddressLine1(line1);
710	            String composed = line1;
711	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
712	                String line2 = normalizeAddress(owner.getAddressLine2());
713	                owner.setAddressLine2(line2);
714	                composed = line1 + " " + line2;
715	            } else {
716	                owner.setAddressLine2(null);
717	            }
718	            owner.setAddress(composed);
719	        } else {
720	            owner.setAddressLine1(null);
721	            owner.setAddressLine2(null);
722	            owner.setAddress(normalizeAddress(owner.getAddress()));
723	        }
724	    }
725	
726	    /**
727	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
728	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
729	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
730	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
731	     *
732	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
733	     *
734	     * @param address the raw address supplied by the client, possibly {@code null}
735	     * @return the normalized address
736	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
737	     *                                 after normalization (required field)
738	     */
739	    private static String normalizeAddress(String address) {
740	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
741	        if (collapsed.isEmpty()) {
742	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
743	                "address must not be blank");
744	        }
745	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
746	        StringBuilder normalized = new StringBuilder();
747	        for (int i = 0; i < tokens.length; i++) {
748	            if (i > 0) {
749	                normalized.append(' ');
750	            }
751	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
752	        }
753	        return normalized.toString();
754	    }
755	
756	    /**
757	     * Determines whether the given whole identity key already belongs to any owner other than the
758	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
759	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
760	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
761	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
762	     *
763	     * @param identityKey the identity key to look for
764	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
765	     * @return {@code true} if another owner already has the same identity key
766	     */
767	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
768	        for (Owner existing : this.clinicService.findAllOwners()) {
769	            if (existing.isDeleted()) {
770	                continue;
771	            }
772	            if (excludeId != null && excludeId.equals(existing.getId())) {
773	                continue;
774	            }
775	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
776	                return true;
777	            }
778	        }
779	        return false;
780	    }
781	
782	    /**
783	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
784	     * (soft) duplicate of: one whose identity key <em>differs</em> from the new owner's while sharing
785	     * the same last-name Soundex code (see {@link IdentityKeyUtils#soundex(String)}) and postcode. A
786	     * hard duplicate (identical identity key) has already been rejected with a 409 before this runs, so
787	     * this flags only the softer same-household-name overlap — in particular two owners with the same
788	     * last name and postcode but different telephones (whose identity keys therefore differ) are a soft
789	     * match rather than a rejected duplicate. The match with the lowest id is returned so the result is
790	     * deterministic when several owners qualify.
791	     *
792	     * @param owner the new owner being created, with its telephone already normalized
793	     * @return the matching existing owner, or {@code null} when none qualifies
794	     */
795	    private Owner findPossibleDuplicate(Owner owner) {
796	        if (owner.getLastName() == null || owner.getPostcode() == null) {
797	            return null;
798	        }
799	        String identityKey = ownerMapper.toIdentityKey(owner);
800	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
801	        return this.clinicService.findAllOwners().stream()
802	            .filter(existing -> !existing.isDeleted())
803	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
804	            .filter(existing -> soundex.equals(IdentityKeyUtils.soundex(existing.getLastName())))
805	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
806	            .min(Comparator.comparingInt(Owner::getId))
807	            .orElse(null);
808	    }
809	
810	}
